// Package icons embeds the app's icons, generated by gen.go.
package icons

import _ "embed"

//go:generate go run gen.go

// TrayTemplate is the macOS menu bar icon: black on transparent, which
// macOS tints for light and dark menu bars.
//
//go:embed tray-template.png
var TrayTemplate []byte

// Tray is the colored tray icon for Linux.
//
//go:embed tray.png
var Tray []byte

// App is the 1024px application icon (Icaro.app's AppIcon.icns is built
// from it on macOS).
//
//go:embed app.png
var App []byte
